function assertPersonaSessionPreserved(before,after,{requireAdvance=false}={}){for(const value of [before,after]){assert(value&&Object.getPrototypeOf(value)===Object.prototype);assert.deepEqual(Object.keys(value),['personaSession']);assert(Array.isArray(value.personaSession));assert.equal(value.personaSession.length,1);assert(value.personaSession[0]&&Object.getPrototypeOf(value.personaSession[0])===Object.prototype);assert.deepEqual(Object.keys(value.personaSession[0]),['row']);assert(value.personaSession[0].row&&Object.getPrototypeOf(value.personaSession[0].row)===Object.prototype);assert.equal(typeof value.personaSession[0].row.last_seen_at,'string');assert(Number.isFinite(Date.parse(value.personaSession[0].row.last_seen_at)));}const beforeRow={...before.personaSession[0].row},afterRow={...after.personaSession[0].row},beforeSeen=Date.parse(beforeRow.last_seen_at),afterSeen=Date.parse(afterRow.last_seen_at);delete beforeRow.last_seen_at;delete afterRow.last_seen_at;assert.deepEqual(afterRow,beforeRow);assert(afterSeen>=beforeSeen,'persona last_seen_at must not decrease');if(requireAdvance)assert(afterSeen>beforeSeen,'authenticated sibling probes must advance last_seen_at');return{identityPreserved:true,livenessAdvanced:afterSeen>beforeSeen};}
