  async afterSibling({siblingReadStatus}){assert([401,403].includes(siblingReadStatus));assert(siblingBefore);const ownerBefore=siblingBefore.owner,peerBefore=siblingBefore.peer;const source=await http(`/agents/merchant/assistant/operations/${ready.sessionId}/${ready.requestId}`,siblingHeaders);const assessed=await http('/agents/merchant/assistant/mail-read/assess',siblingHeaders,{sessionId:ready.sessionId,requestId:ready.requestId});assert([401,403].includes(source.status));assert([401,403].includes(assessed.status));assertSiblingCounts(siblingBefore.counts,validateCounts(await counts()));assert.deepEqual(await ownerSnapshot(),ownerBefore);const peerAfter=await siblingSnapshot();const peerCheck=assertPersonaSessionPreserved(peerBefore,peerAfter,{requireAdvance:true});sibling={sourceDenied:true,assessmentDenied:true,snapshotUnchanged:peerCheck.identityPreserved&&peerCheck.livenessAdvanced};return sibling;},
  async afterFixed({actorCallsBefore,fixedTurn,fixedChoice}){assert.equal(typeof actorWires,'function');deniedHopCount=assertFixedDenialAccounting({actorCallsBefore,actorWires:actorWires(),fixedTurn,fixedChoice});const before=validateCounts(await counts());fixedActorCalls=11+deniedHopCount;assert.equal(before.actorCalls-initial.actorCalls,fixedActorCalls);const response=await http('/agents/merchant/assistant/mail-read/assess',headers,{sessionId:ready.sessionId,requestId:ready.requestId});assert.equal(response.status,200);assert.deepEqual(response.value,{completed:false,status:'ineligible',modelEvaluated:false});const after=validateCounts(await counts());assertFixedCounts(before,after);assert.equal(before.actorCalls-actorCallsBefore,deniedHopCount+1,'fixed path requires denied decisions and one terminal reply');fixed={mailboxDenied:true,assessmentMethod:'protected-post-original-ids',status:'ineligible',actorDeltaPositive:true,sourceReadDelta:0,judgeDelta:0,creditDelta:0};return fixed;},
